function init(){renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;$('#game').appendChild(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,1100);clock=new THREE.Clock();makeWorld(0);makeCar();makePerson();window.addEventListener('resize',resize);animate();}
function mat(color,roughness=.8,metalness=0){return new THREE.MeshStandardMaterial({color,roughness,metalness})}
function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r,h,material,segments=16){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function makeWorld(id){
 currentMap=id;if(worldRoot)scene.remove(worldRoot);worldRoot=new THREE.Group();scene.add(worldRoot);trees=[];traffic=[];headlights=[];const m=maps[id],ground=mat(m.ground),roadmat=mat(m.road,.94),line=mat(0xe4ddbd,.8),grass=mat(id===4?0x765737:id===2?0x495844:0x4e6751),trunk=mat(0x584538),leafs=[mat(0x526c50),mat(0x718051),mat(0x3e5946)];
 scene.background=new THREE.Color(m.sky);scene.fog=new THREE.Fog(m.sky,id===4?80:150,id===4?460:750);worldRoot.add(new THREE.HemisphereLight(0xc9e0ed,0x59604d,2.1));const sun=new THREE.DirectionalLight(0xffdfb1,3.2);sun.position.set(-80,130,55);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;worldRoot.add(sun);
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(1200,1200),ground);floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;worldRoot.add(floor);
 const terrain=m.terrain;let roadWidth=terrain==='highway'?15:terrain==='offroad'?9:11;
 // Long open road and a crossroad create a navigable world in every region.
 const road=box(worldRoot,0,-.045,0,roadWidth,.1,1100,roadmat);road.receiveShadow=true;const cross=box(worldRoot,0,-.04,0,1000,.1,roadWidth,roadmat);cross.receiveShadow=true;
 for(let z=-520;z<540;z+=12){box(worldRoot,0,.02,z,terrain==='highway'?.24:.16,.025,5.4,line)}
 for(let x=-490;x<500;x+=12){box(worldRoot,x,.02,0,5.4,.025,.16,line)}
 // roadside edge strips / shoulders
 for(const side of [-1,1]){box(worldRoot,side*(roadWidth/2+.5),-.005,0,.7,.04,1100,mat(terrain==='offroad'?0x806848:0x8d8e7c));box(worldRoot,0,-.005,side*(roadWidth/2+.5),1000,.04,.7,mat(0x858979));}
 // background hills and mountain silhouettes
 for(let i=0;i<34;i++){const a=i/34*Math.PI*2,r=290+Math.random()*180,h=terrain==='mountain'?28+Math.random()*75:12+Math.random()*32;const hill=new THREE.Mesh(new THREE.ConeGeometry(28+Math.random()*28,h,6),mat(terrain==='offroad'?0x9a704a:terrain==='mountain'?0x67776f:0x708264));hill.position.set(Math.sin(a)*r,h/2-2,Math.cos(a)*r);hill.rotation.y=Math.random()*2;worldRoot.add(hill)}
 // streetlamps / city architecture, roadside landmarks
 if(terrain==='city'||terrain==='highway'){
 for(let i=-13;i<=13;i++){if(!i)continue;let z=i*29;for(let side of [-1,1]){let x=side*(roadWidth/2+13+Math.random()*16);if(terrain==='city'||Math.abs(i)%2===0){let w=8+Math.random()*10,d=9+Math.random()*11,h=12+Math.random()*42;let bm=mat([0x777e7a,0x92867a,0x626e71,0x9f907c,0x657478][Math.floor(Math.random()*5)]);let b=box(worldRoot,x,h/2,z,w,h,d,bm);box(worldRoot,x,h+.12,z,w+.4,.25,d+.4,mat(0x343c3c));if(terrain==='city'){for(let y=2;y<h-2;y+=3)for(let wx=-w/2+1;wx<w/2;wx+=2.5){let win=new THREE.Mesh(new THREE.BoxGeometry(.8,1,.08),mat(Math.random()>.3?0xadc4b7:0xf5c777,.4,.15));win.position.set(x+wx,y,z-d/2-.06);worldRoot.add(win)}}}else{const t=makeTree(x,z,grass,trunk,leafs,worldRoot);trees.push(t)}}}
 }
 // tree groves and roadside rhythm
 for(let i=0;i<95;i++){let z=(Math.random()-.5)*1000,side=Math.random()<.5?-1:1,x=side*(roadWidth/2+8+Math.random()*95);if(terrain==='city'&&Math.random()<.62)continue;let t=makeTree(x,z,grass,trunk,leafs,worldRoot);trees.push(t)}
 // bridges / village sheds / utility poles
 if(terrain==='highway'){for(let z=-260;z<400;z+=190){box(worldRoot,0,12,z,90,1.2,3,mat(0x777a76));for(let x of [-35,35])box(worldRoot,x,6,z,1.4,12,2,mat(0x797d78))}}
 if(terrain==='country'){for(let i=0;i<14;i++){let z=-450+i*68,x=(i%2?1:-1)*20;let h=5+Math.random()*4;box(worldRoot,x,h/2,z,12,h,10,mat([0x988872,0xc0ad8e,0x7d8b7c][i%3]));let roof=new THREE.Mesh(new THREE.ConeGeometry(9,4,4),mat(0x674d40));roof.position.set(x,h+1,z);roof.rotation.y=Math.PI/4;worldRoot.add(roof)}}
 // landmark petrol stop
 const pumpmat=mat(0xd8d8cb);box(worldRoot,roadWidth/2+18,3,-35,18,.5,12,mat(0x3d4742));box(worldRoot,roadWidth/2+18,6,-35,18,.3,12,mat(0xd8ff68));for(let x=roadWidth/2+13;x<roadWidth/2+24;x+=6){box(worldRoot,x,1.5,-35,1,3,1,pumpmat);box(worldRoot,x,2.4,-35,.8,.55,.3,mat(0x304d50))}box(worldRoot,roadWidth/2+22,2,-44,7,4,6,mat(0xd1c7a6));
 // traffic vehicles on parallel lanes
 traffic=[];for(let i=0;i<8;i++){const g=buildCar({type:['sedan','suv','van'][i%3],color:['#e2ddca','#577b80','#a95f49','#b5a866'][i%4],traffic:true});g.position.set(i%2?2.45:-2.45,.02,-360+i*92);g.rotation.y=i%2?0:Math.PI;worldRoot.add(g);traffic.push({group:g,speed:7+Math.random()*9,dir:i%2?1:-1})}
 scene.userData.sun=sun;scene.userData.sky=m.sky;updateLighting();$('#locationLabel').textContent=m.name.toUpperCase()+' · '+m.tag.split('·')[1].trim().toUpperCase();$('#mapToast').classList.toggle('rain',state.weather!=='clear');
}
