function updateLighting(){if(!scene)return;let sun=scene.userData.sun;if(!sun)return;let night=state.day==='night',mid=state.day==='day';scene.background.set(night?0x101a2d:mid?0x8bbbd0:maps[currentMap].sky);scene.fog.color.set(night?0x18202d:mid?0x9bb7b5:maps[currentMap].sky);sun.intensity=night?.48:mid?3.5:3.2;sun.color.set(night?0x9aaed1:mid?0xfff1d0:0xffdfb1);scene.fog.near=state.weather==='fog'?18:130;scene.fog.far=state.weather==='fog'?210:700}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}

