function renderGarage(){let list=vehicles.map((v,i)=>[v,i]).filter(([v])=>v.kind===activeKind);$('#vehicleGrid').innerHTML=list.map(([v,i])=>`<div class="vehicle-card ${i===selected?'active':''}" data-id="${i}"><div class="swatch" style="--swatch:${v.color}"></div><strong>${v.name}</strong><small>${v.desc.slice(0,68)}…</small><div class="statbar"><i style="width:${Math.min(100,v.top/3.3)}%"></i></div></div>`).join('');$$('.vehicle-card').forEach(el=>el.onclick=()=>{selected=+el.dataset.id;renderGarage();$('#vehicleDescription').textContent=vehicles[selected].desc;updateSelectionUI()});$('#vehicleDescription').textContent=vehicles[selected].desc}
function renderMaps(){$('#mapGrid').innerHTML=maps.map((m,i)=>`<div class="map-card ${i===selectedMap?'active':''}" data-id="${i}" style="background:linear-gradient(145deg,${new THREE.Color(m.sky).getStyle()}22,#ffffff04)"><div class="eyebrow">${m.tag}</div><strong>${m.name}</strong><small>${m.desc}</small></div>`).join('');$$('.map-card').forEach(el=>el.onclick=()=>{selectedMap=+el.dataset.id;renderMaps();$('#mapDescription').textContent=maps[selectedMap].desc})}
function updateSelectionUI(){if(!vehicles[selected])return;$('#cardCar').textContent=vehicles[selected].name;$('#cardMap').textContent=maps[selectedMap].name;$('#cardWeather').textContent=`${state.day==='night'?'Night drive':state.day==='day'?'Midday':'Golden hour'} · ${state.weather==='rain'?'Light rain':state.weather==='fog'?'Fog':'Clear'}`;$('#topBalance').innerHTML=`CR <b>${balance.toLocaleString()}</b>`}
function showPanel(id){$$('.panel').forEach(p=>p.classList.remove('open'));$('#'+id).classList.add('open')}
function startDrive(){selected=Math.max(0,selected);makeWorld(selectedMap);makeCar();$('#home').style.display='none';$('#homeCard').style.display='none';$('#hud').classList.add('active');state.running=true;state.paused=false;$('#pauseScreen').classList.remove('open');updateLighting();updateSelectionUI();toast('Welcome to '+maps[selectedMap].name+' — enjoy the drive');}
function endDrive(){state.running=false;state.paused=false;state.onFoot=false;person.visible=false;$('#pauseScreen').classList.remove('open');$('#hud').classList.remove('active');$('#home').style.display='flex';$('#homeCard').style.display='block';save()}
function enterExit(){if(!state.running)return;if(!state.onFoot){if(Math.abs(state.speed)>4){toast('Slow down before stepping out');return}state.onFoot=true;person.position.copy(car.position).add(new THREE.Vector3(2,0,0));person.rotation.y=state.heading;person.visible=true;car.visible=true;toast('On foot · press E near your car to get back in');}else{if(person.position.distanceTo(car.position)<5){state.onFoot=false;person.visible=false;toast('Back behind the wheel');}else toast('Get a little closer to your vehicle first')}}
const keys=new Set();window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k==='escape'||k==='p'){if(state.running){state.paused=!state.paused;$('#pauseScreen').classList.toggle('open',state.paused)}}if(k==='e')enterExit();if(k==='c')cycleCamera();if(k==='h')toggleLights();if(k==='q')cycleGear(-1);if(k==='r')cycleGear(1);if(k==='f')state.hand=!state.hand;if(k==='1'||k==='2'||k==='3'||k==='4'||k==='5'||k==='6'){state.manual=+k;state.gear='D';toast('Manual gear '+k)}if(k==='x')state.signals=state.signals?0:1});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function cycleCamera(){state.camera=(state.camera+1)%5;let labels=['COCKPIT','DRIVER','CHASE','FRONT','SIDE'];$('#cameraBtn').textContent='CAM · '+labels[state.camera];toast('Camera: '+labels[state.camera])}
function cycleGear(dir){let gears=['P','R','N','D'];let i=gears.indexOf(state.gear);state.gear=gears[(i+dir+gears.length)%gears.length];state.manual=0;toast('Gear · '+state.gear)}
function toggleLights(){state.lights=!state.lights;$('#lightBtn').classList.toggle('on',state.lights);toast(state.lights?'Headlights on':'Headlights off')}
$('#playBtn').onclick=startDrive;$('#garageBtn').onclick=()=>{renderGarage();showPanel('garagePanel')};$('#mapsBtn').onclick=()=>{renderMaps();showPanel('mapsPanel')};$('#vehicleTabs').onclick=e=>{let b=e.target.closest('[data-kind]');if(!b)return;activeKind=b.dataset.kind;$$('#vehicleTabs .tab').forEach(t=>t.classList.toggle('active',t===b));renderGarage()};$('#selectVehicle').onclick=()=>{updateSelectionUI();save();$$('.panel').forEach(p=>p.classList.remove('open'));if(state.running)makeCar();toast(vehicles[selected].name+' ready')};$('#selectMap').onclick=()=>{updateSelectionUI();save();$$('.panel').forEach(p=>p.classList.remove('open'));toast(maps[selectedMap].name+' selected');if(state.running)startDrive()};$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('.panel').classList.remove('open'));$$('.panel').forEach(p=>p.addEventListener('click',e=>{if(e.target===p)p.classList.remove('open')}));$('#settingsBtn')?.addEventListener('click',()=>showPanel('settingsPanel'));$('#cameraBtn').onclick=cycleCamera;$('#mapHudBtn').onclick=()=>{selectedMap=(selectedMap+1)%maps.length;startDrive()};$('#pauseBtn').onclick=()=>{state.paused=true;$('#pauseScreen').classList.add('open')};$('#resumeBtn').onclick=()=>{state.paused=false;$('#pauseScreen').classList.remove('open')};$('#exitBtn').onclick=endDrive;$('#signalBtn').onclick=()=>{state.signals=(state.signals+1)%3;$('#signalBtn').classList.toggle('on',!!state.signals);toast(['Signals off','Left signal','Right signal'][state.signals])};$('#lightBtn').onclick=toggleLights;$('#customBtn').onclick=()=>showPanel('customPanel');$('#repairBtn').onclick=()=>{if(balance>=250){balance-=250;state.damage=0;updateSelectionUI();toast('Vehicle repaired · CR 250')}else toast('Not enough credits')};$('#paint').oninput=e=>{if(car?.userData.paint)car.userData.paint.color.set(e.target.value)};$('#weather').onchange=e=>{state.weather=e.target.value;updateLighting();updateSelectionUI();toast('Weather: '+e.target.options[e.target.selectedIndex].text)};$('#timeOfDay').onchange=e=>{state.day=e.target.value;updateLighting();updateSelectionUI();toast('Time changed')};$('#quality').onchange=e=>{renderer.setPixelRatio(Math.min(devicePixelRatio,e.target.value==='Performance'?1:e.target.value==='Balanced'?1.3:1.8));toast('Graphics: '+e.target.value)};$('#volume').oninput=e=>{if(audioCtx&&engineOsc)engineOsc.gain.gain.value=e.target.value/100*.025};
// Add the settings entry from the home actions without crowding the screen.
const settingsButton=document.createElement('button');settingsButton.className='ghost';settingsButton.textContent='SETTINGS';settingsButton.onclick=()=>showPanel('settingsPanel');$('.intro .actions').appendChild(settingsButton);
$('#steerWrap').addEventListener('pointerdown',e=>{e.preventDefault();$('#steerWrap').setPointerCapture(e.pointerId);state.steer=Math.max(-1,Math.min(1,(e.clientX-innerWidth*.18)/(innerWidth*.22)-1))});$('#steerWrap').addEventListener('pointermove',e=>{if(e.buttons){state.steer=Math.max(-1,Math.min(1,(e.clientX-innerWidth*.18)/(innerWidth*.22)-1));$('#steering').style.setProperty('--turn',state.steer*120+'deg')}});$('#steerWrap').addEventListener('pointerup',()=>{state.steer=0;$('#steering').style.setProperty('--turn','0deg')});
function bindPedal(id,key){let el=$('#'+id);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);el.classList.add('active');state[key]=1});for(let type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,()=>{el.classList.remove('active');state[key]=0})}bindPedal('accelerator','throttle');bindPedal('brake','braking');bindPedal('handbrake','hand');$('#handbrake').addEventListener('click',()=>{state.hand=!state.hand;$('#handbrake').classList.toggle('active',state.hand)});
// M key toggles map selection; gears are directly tappable in the dashboard.
$('#gearRead').style.cursor='pointer';$('#gearRead').onclick=()=>cycleGear(1);$('#gearRead').ondblclick=()=>cycleGear(-1);
function startEngineSound(){try{audioCtx=new (window.AudioContext||window.webkitAudioContext)();engineOsc=audioCtx.createOscillator();let gain=audioCtx.createGain();engineOsc.type='sawtooth';gain.gain.value=0;engineOsc.connect(gain);gain.connect(audioCtx.destination);engineOsc.start()}catch(e){}}
init();startEngineSound();

